"""Full training, evaluation, and reporting pipeline for multi-touch attribution."""

from __future__ import annotations

import argparse
import json
import platform
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import scipy

from . import config, data, metrics, models

CAVEATS = [
    "All journeys and touches are generated by a synthetic Markov customer journey simulator.",
    "Real customer paths include ad-blockers, multi-device cross-tracking loss, and cookie expiration.",
    "Channels are modeled with fixed base costs; programmatic ad auctions exhibit dynamic bid pricing.",
    "Removal effect Markov attribution assumes first-order state transitions without higher-order history memory.",
]


def _versions() -> dict[str, str]:
    return {
        "python": platform.python_version(),
        "numpy": np.__version__,
        "scipy": scipy.__version__,
    }


def run_pipeline(
    results_dir: Path | None = None,
    fast_mode: bool = False,
) -> tuple[dict, dict]:
    """Execute the full attribution evaluation pipeline."""
    out_dir = results_dir or config.RESULTS_DIR
    out_dir.mkdir(parents=True, exist_ok=True)

    n_train = config.FAST_TRAIN_JOURNEYS if fast_mode else config.TRAIN_JOURNEYS
    n_test = config.FAST_TEST_JOURNEYS if fast_mode else config.TEST_JOURNEYS

    train_ds = data.generate_journeys(n_train, seed=config.SEED)
    test_ds = data.generate_journeys(n_test, seed=config.SEED + 100)

    # Calculate true population counterfactual Shapley credit on test cohort
    true_shares = data.calculate_true_causal_credit(test_ds)

    # Fit attribution models on training journeys
    lt_model = models.LastTouchAttribution().fit(train_ds)
    ft_model = models.FirstTouchAttribution().fit(train_ds)
    lin_model = models.LinearAttribution().fit(train_ds)
    pos_model = models.PositionBasedAttribution().fit(train_ds)
    td_model = models.TimeDecayAttribution().fit(train_ds)
    markov_model = models.MarkovAttribution().fit(train_ds)

    fitted_models = {
        "last_touch": lt_model,
        "first_touch": ft_model,
        "linear": lin_model,
        "position_based": pos_model,
        "time_decay": td_model,
        "markov": markov_model,
    }

    # Evaluate each model on test cohort
    models_summary: dict[str, dict] = {}
    for name, m in fitted_models.items():
        shares = m.channel_shares_
        mae = metrics.channel_shares_mae(shares, true_shares)
        spearman = metrics.channel_shares_spearman(shares, true_shares)
        realloc = metrics.evaluate_budget_reallocation(shares, test_ds)

        models_summary[name] = {
            "channel_shares": {ch: round(shares[ch], 4) for ch in config.CHANNELS},
            "share_mae": round(mae, 4),
            "share_spearman": round(spearman, 4),
            "incremental_conversions": realloc["incremental_conversions"],
            "channel_spend": realloc["channel_spend"],
        }

    # Oracle evaluation
    oracle_realloc = metrics.evaluate_budget_reallocation(true_shares, test_ds)
    models_summary["oracle"] = {
        "channel_shares": {ch: round(true_shares[ch], 4) for ch in config.CHANNELS},
        "share_mae": 0.0,
        "share_spearman": 1.0,
        "incremental_conversions": oracle_realloc["incremental_conversions"],
        "channel_spend": oracle_realloc["channel_spend"],
    }

    # Headline model (Markov) bootstrap uncertainty
    headline_mae = models_summary[config.HEADLINE_MODEL]["share_mae"]
    n_resamples = 100 if fast_mode else 500
    _pt_est, ci_95 = metrics.bootstrap_share_mae(
        test_ds,
        markov_model.channel_shares_,
        n_resamples=n_resamples,
        seed=config.SEED,
    )

    # Budget reallocation gain
    lt_convs = models_summary["last_touch"]["incremental_conversions"]
    mk_convs = models_summary["markov"]["incremental_conversions"]
    realloc_gain = (mk_convs - lt_convs) / lt_convs if lt_convs > 0 else 0.0

    # Decision Gate evaluation
    checks = {
        "channel_credit_mae_below_threshold": bool(headline_mae < config.MAX_CREDIT_SHARE_MAE),
        "beats_last_touch_mae": bool(headline_mae < models_summary["last_touch"]["share_mae"]),
        "reallocation_gain_at_least_5pct": bool(realloc_gain >= config.MIN_REALLOCATION_GAIN),
    }
    gate_passed = all(checks.values())

    # Traps measurement
    # Trap 1: Last-touch attribution bias
    lt_shares = models_summary["last_touch"]["channel_shares"]
    trap_last_touch = {
        "display_true_credit_share": round(true_shares["display"], 4),
        "display_last_touch_share": round(lt_shares["display"], 4),
        "search_true_credit_share": round(true_shares["search"], 4),
        "search_last_touch_share": round(lt_shares["search"], 4),
        "email_true_credit_share": round(true_shares["email"], 4),
        "email_last_touch_share": round(lt_shares["email"], 4),
        "finding": (
            "Last touch starves top-of-funnel Display and over-credits bottom-of-funnel Email and Search, "
            "missing that Display touches initiate customer consideration."
        ),
    }

    # Trap 2: Ignoring organic baseline conversions
    total_test_conv = test_ds.conversions
    expected_organic_conv = sum(j.organic_prob for j in test_ds.journeys)
    organic_share = expected_organic_conv / total_test_conv if total_test_conv > 0 else 0.0
    trap_organic = {
        "total_test_conversions": total_test_conv,
        "expected_organic_conversions": round(expected_organic_conv, 1),
        "organic_conversion_share": round(organic_share, 4),
        "finding": (
            "Heuristic attribution assigns 100% of conversions to ad channels, ignoring that a large "
            "fraction of converting users would have converted organically with zero marketing touches."
        ),
    }

    # Trap 3: Linear attribution dilution
    lin_shares = models_summary["linear"]["channel_shares"]
    trap_linear = {
        "linear_display_share": round(lin_shares["display"], 4),
        "true_display_share": round(true_shares["display"], 4),
        "linear_share_mae": round(models_summary["linear"]["share_mae"], 4),
        "finding": (
            "Linear attribution spreads credit equally across all touchpoints (1/K), diluting decisive "
            "discovery and closing touches by over-crediting passive incidental touches."
        ),
    }

    # Error analysis by journey length
    length_buckets = ["1", "2", "3", "4+"]
    segment_data: dict[str, dict] = {}
    for bucket in length_buckets:
        if bucket == "4+":
            sub_journeys = [j for j in test_ds.journeys if len(j.path) >= 4]
        else:
            sub_journeys = [j for j in test_ds.journeys if len(j.path) == int(bucket)]

        n_sub = len(sub_journeys)
        conv_sub = sum(j.converted for j in sub_journeys)
        conv_rate = (conv_sub / n_sub) if n_sub > 0 else 0.0

        segment_data[f"length_{bucket}"] = {
            "total_journeys": n_sub,
            "conversions": conv_sub,
            "conversion_rate": round(conv_rate, 4),
        }

    # Plot attribution comparison
    _plot_attribution(models_summary, true_shares, out_dir / "attribution_comparison.png")

    # Assemble metrics.json
    metrics_payload = {
        "project": "18-multi-touch-attribution",
        "data_source": "simulated_known_truth",
        "fast_mode": fast_mode,
        "seed": config.SEED,
        "versions": _versions(),
        "data": {
            "train_journeys": n_train,
            "test_journeys": n_test,
            "channels": config.CHANNELS,
            "sha256": train_ds.sha256,
        },
        "assumptions": {
            "base_organic_logit": config.BASE_LOGIT,
            "reallocation_budget": config.REALLOCATION_BUDGET,
            "channel_costs": config.CHANNEL_COSTS,
            "channel_lifts": config.CHANNEL_LIFTS,
        },
        "models": models_summary,
        "headline": {
            "model": config.HEADLINE_MODEL,
            "value": round(headline_mae, 4),
            "ci_95": ci_95,
            "ci_method": f"percentile bootstrap over test journeys, {n_resamples} resamples",
        },
        "budget_allocation": {
            "reallocation_budget": config.REALLOCATION_BUDGET,
            "last_touch_conversions": lt_convs,
            "markov_conversions": mk_convs,
            "relative_gain": round(realloc_gain, 4),
            "relative_gain_pct": round(realloc_gain * 100.0, 2),
        },
        "gate": {
            "rule": config.GATE_RULE,
            "checks": checks,
            "passed": gate_passed,
        },
        "traps": {
            "last_touch_bias": trap_last_touch,
            "ignoring_organic_baseline": trap_organic,
            "linear_dilution": trap_linear,
        },
        "caveats": CAVEATS,
    }

    # Assemble error_analysis.json
    error_analysis_payload = {
        "project": "18-multi-touch-attribution",
        "fast_mode": fast_mode,
        "journey_length_segments": segment_data,
        "channel_costs": config.CHANNEL_COSTS,
        "channel_marginal_lifts": config.CHANNEL_LIFTS,
        "post_hoc_notes": [
            {
                "status": "Markov attribution partially recovers top-of-funnel credit compared to last touch, but remains constrained by first-order memoryless state representations.",
            }
        ],
    }

    (out_dir / "metrics.json").write_text(json.dumps(metrics_payload, indent=2), encoding="utf-8")
    (out_dir / "error_analysis.json").write_text(
        json.dumps(error_analysis_payload, indent=2), encoding="utf-8"
    )

    return metrics_payload, error_analysis_payload


def _plot_attribution(models_summary: dict, true_shares: dict, out_path: Path) -> None:
    """Generate bar chart comparing channel shares across attribution models."""
    _fig, ax = plt.subplots(figsize=(9, 5))
    x = np.arange(len(config.CHANNELS))
    width = 0.13

    model_names = ["last_touch", "first_touch", "linear", "position_based", "markov", "oracle"]
    labels = [
        "Last Touch",
        "First Touch",
        "Linear",
        "Position Based",
        "Markov (Removal)",
        "True Causal",
    ]

    for i, (m_key, label) in enumerate(zip(model_names, labels, strict=True)):
        shares = [models_summary[m_key]["channel_shares"][ch] for ch in config.CHANNELS]
        ax.bar(x + (i - 2.5) * width, shares, width, label=label)

    ax.set_ylabel("Attributed Credit Share")
    ax.set_title("Multi-Touch Attribution: Heuristic Baselines vs Markov Chain vs True Causal")
    ax.set_xticks(x)
    ax.set_xticklabels([ch.capitalize() for ch in config.CHANNELS])
    ax.legend(frameon=True)
    ax.grid(axis="y", linestyle="--", alpha=0.5)

    plt.tight_layout()
    plt.savefig(out_path, dpi=150)
    plt.close()


def main() -> None:
    parser = argparse.ArgumentParser(description="Run multi-touch attribution evaluation.")
    parser.add_argument(
        "--fast", action="store_true", help="Run quick smoke test with reduced dataset."
    )
    parser.add_argument(
        "--write-checksum", action="store_true", help="Write dataset SHA-256 to CHECKSUMS.txt."
    )
    args = parser.parse_args()

    metrics_res, _ = run_pipeline(fast_mode=args.fast)

    if args.write_checksum:
        sha = metrics_res["data"]["sha256"]
        config.CHECKSUM_FILE.parent.mkdir(parents=True, exist_ok=True)
        config.CHECKSUM_FILE.write_text(f"{sha}  simulated_journeys\n", encoding="utf-8")
        print(f"Wrote checksum {sha} to {config.CHECKSUM_FILE}")

    print(f"Pipeline complete. Gate passed: {metrics_res['gate']['passed']}")


if __name__ == "__main__":
    main()
